function esc(s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
function normHarga(s) {
  s = String(s == null ? '' : s).toLowerCase().trim();
  const mt = s.match(/^([\d.,]+)\s*(rb|ribu|k|jt|juta)?$/);
  if (!mt) return 0;
  let num = mt[1];
  const mult = ({ rb: 1e3, ribu: 1e3, k: 1e3, jt: 1e6, juta: 1e6 })[mt[2] || ''] || 1;
