// Parse update Telegram (message/callback/foto) + whitelist user aktif + duplicate shield (pola Spending Bot)
const u = $('TG Update').first().json;
const cb = u.callback_query || null;
const msg = u.message || u.edited_message || (cb ? cb.message : null);
if (!msg || !msg.from || msg.from.is_bot) return [];
const jid = String(msg.chat.id);
const uid = String(cb ? cb.from.id : msg.from.id);
if (jid !== uid) return []; // v1: chat pribadi saja
const cfg = $('Config').first().json;
const owners = String(cfg.owner_ids || '').split(',').map(function (s) { return s.trim(); }).filter(Boolean);
const users = $input.all().map(function (i) { return i.json; }).filter(function (r) { return r && r.user_id; });
const me = users.find(function (r) { return String(r.user_id) === uid; });
let role = '';
if (owners.indexOf(uid) >= 0) role = 'owner';
else if (me && String(me.aktif).toUpperCase() !== 'FALSE') role = String(me.role || 'kasir').toLowerCase();
if (!role) {
  const name0 = (cb ? cb.from.first_name : msg.from.first_name) || msg.from.username || '';
  return [{ json: { blocked: true, chat_id: jid, user_id: uid, nama: name0, text: '', kind: 'blocked', role: '' } }];
}
const stat = $getWorkflowStaticData('global');
stat.seen = stat.seen || {};
const now = Date.now();
for (const k of Object.keys(stat.seen)) { if (now - stat.seen[k] > 120000) delete stat.seen[k]; }
let text = '', kind = 'text', file_id = '';
if (cb && cb.data) { kind = 'callback'; text = String(cb.data).replace(/^kb:/, '').trim(); }
else if (msg.photo && msg.photo.length) { kind = 'photo'; file_id = msg.photo[msg.photo.length - 1].file_id; text = (msg.caption || '').trim(); }
else { text = (msg.text || msg.caption || '').trim(); if (!text) return []; }
const msgId = kind === 'callback' ? 'cb-' + (cb.id || now) : String(msg.message_id || ('msg-' + now));
if (stat.seen[msgId]) return [];
if (kind !== 'callback') {
  const dupKey = 'u:' + jid + ':' + (kind === 'text' ? text.toLowerCase() : kind + ':' + file_id + ':' + text);
  if (stat.seen[dupKey] && now - stat.seen[dupKey] < 60000) return [];
  stat.seen[dupKey] = now;
}
stat.seen[msgId] = now;
const nama = String((me && me.nama) || (cb ? cb.from.first_name : msg.from.first_name) || msg.from.username || 'Tanpa Nama');
return [{ json: { chat_id: jid, user_id: uid, nama: nama, role: role, text: text, kind: kind, file_id: file_id } }];

