// Tentukan rute dari teks/jenis pesan + state pending aktif.
// CATATAN: input node ini = baris tab Pending; pesan user diambil dari Extract & Filter.
const m = $('Extract & Filter').first().json;
if (m.blocked) return [{ json: Object.assign({}, m, { route: 'blocked', pending_stage: '', draft: {}, args: '' }) }];
const low = String(m.text || '').trim().toLowerCase();
const rows = $input.all().map(function (i) { return i.json; }).filter(function (r) { return r && r.jid; });
let pending = null;
for (const r of rows) {
  const st = String(r.status || 'active');
  if (r.jid === m.chat_id && st !== 'done' && st !== 'cancelled') {
    if (!pending || String(r.timestamp) >= String(pending.timestamp)) pending = r;
  }
}
const TTL = 2 * 60 * 60 * 1000; // draft > 2 jam dianggap hangus
if (pending) {
  const age = Date.now() - (Date.parse(String(pending.timestamp).replace(' WIB', '+07:00')) || 0);
  if (age > TTL) pending = null;
}
const stage = pending ? pending.stage : '';
let draft = {};
if (pending && pending.draft_json) { try { draft = JSON.parse(pending.draft_json); } catch (e) { draft = {}; } }
const active = !!stage;
const isCmd = function (c) { return new RegExp('^/?' + c + '(@[a-z_]+)?(\\s|$)', 'i').test(low); };
const mt = String(m.text || '').trim().match(/^\/?[a-z_]+(@[a-z_]+)?\s*([\s\S]*)$/i);
const args = mt ? mt[2].trim() : '';
const isYes = /^(1|ya|yes|y|oke|ok|betul|benar|simpan)$/.test(low);
const isNo = /^(2|tidak|no|n|jangan)$/.test(low);
const cbx = m.kind === 'callback';
let route = 'fallback';
if (cbx && /^per_/.test(low)) route = 'laporan_calc';
else if (m.kind === 'photo') route = 'photo';
else if (isCmd('start') || isCmd('help') || /^(menu|panduan)$/.test(low)) route = 'help';
else if (isCmd('batal') || low === 'cancel') route = active ? 'cancel' : 'void';
else if (isCmd('setup')) route = m.role === 'owner' ? 'setup' : 'fallback';
else if (active && /^setup_/.test(stage)) route = 'setup_step';
else if (isCmd('user') || (active && /^user_/.test(stage))) route = m.role === 'owner' ? 'user_cmd' : 'fallback';
else if (isCmd('jual') || (active && /^jual_/.test(stage))) route = 'jual';
else if (isCmd('beli') || (active && /^beli_/.test(stage) && !cbx)) route = 'beli';
else if (isCmd('saldo') || /^(kas|cek kas)$/.test(low)) route = 'saldo';
else if (isCmd('laporan')) route = args ? 'laporan_calc' : 'laporan_ask';
else if (isCmd('stok')) route = 'stok';
else if (isCmd('produk') || (active && /^p_/.test(stage))) route = m.role === 'owner' ? 'produk' : 'fallback';
else if (active && stage === 'void_pick' && /^pick:\d+$/.test(low)) route = 'void';
else if (active && stage === 'void_confirm' && (isYes || isNo)) route = 'void';
else if (active && stage === 'jual_pay' && /^(pay_(cash|qris|transfer|ewallet)|cash|qris|transfer|e-?wallet)$/.test(low)) route = 'jual';
else if (active && (stage === 'jual_proof' || stage === 'jual_nominal') && /^[\d.,\s]*(rb|ribu|k|jt|juta)?\s*$/.test(low)) route = 'jual';
else if (active && stage === 'confirm' && (isYes || isNo)) route = 'confirm';
else if (active && stage === 'beli_metode' && /^(pay_(cash|qris|transfer|ewallet)|cash|qris|transfer|e-?wallet)$/.test(low)) route = 'beli';
else if (active && stage === 'beli_cat' && /^cat_(bb|ops|sewa|gaji|lain)$/.test(low)) route = 'beli';
else if (active && stage === 'beli_proof' && /^(skip|tanpa (foto|nota))$/.test(low)) route = 'beli';
else if (active && stage === 'p_jenis' && /^jenis_(barang|jasa)$/.test(low)) route = 'produk';
return [{ json: Object.assign({}, m, { route: route, pending_stage: stage || '', draft: draft, args: args }) }];

