const m = $('Router').first().json;
const low = String(m.text || '').trim().toLowerCase();
const stage = m.pending_stage;
const numOnly = /^[\d.,\s]*(rb|ribu|k|jt|juta)?\s*$/.test(low) && /\d/.test(low);
const metodeToken = (low.match(/^(?:pay_)?(cash|qris|transfer|e-?wallet)$/) || [])[1];
const catToken = (low.match(/^cat_(bb|ops|sewa|gaji|lain)$/) || [])[1];
const isNew = !m.draft || m.draft.kind !== 'beli' || !/^beli_/.test(stage);
if (isNew) {
  const d = { kind: 'beli', keterangan: String(m.args || '').slice(0, 120), nominal: null, kategori: '', metode: '', bukti_link: '', bukti_status: '', operator: { id: m.user_id, nama: m.nama } };
  if (d.keterangan) return [{ json: { chat_id: m.chat_id, text: '💸 <b>Pengeluaran</b>\n' + esc(d.keterangan) + '\n\nNominalnya berapa? (mis. <code>50rb</code> atau <code>1,5jt</code>)', pending_row: pr(m.chat_id, 'beli_amount', d) } }];
  return [{ json: { chat_id: m.chat_id, text: '💸 <b>Catat Pengeluaran</b>\n\nBeli apa? (mis. <code>gula 5kg</code>)', pending_row: pr(m.chat_id, 'beli_desc', d) } }];
}
const d = JSON.parse(JSON.stringify(m.draft));
if (stage === 'beli_desc') {
  d.keterangan = String(m.text || '').slice(0, 120);
  return [{ json: { chat_id: m.chat_id, text: 'Nominalnya berapa? (mis. <code>50rb</code>)', pending_row: pr(m.chat_id, 'beli_amount', d) } }];
}
if (stage === 'beli_amount' && numOnly) {
  d.nominal = normHarga(low);
  if (!d.nominal) return [{ json: { chat_id: m.chat_id, text: 'Nominalnya kok 0? Coba tulis lagi, mis. <code>50rb</code>', pending_row: pr(m.chat_id, 'beli_amount', d) } }];
  return [{ json: { chat_id: m.chat_id, text: 'Bayar pakai apa?', kb: [[{ text: '💵 Cash', data: 'pay_cash' }, { text: '📱 QRIS', data: 'pay_qris' }], [{ text: '🏦 Transfer', data: 'pay_transfer' }, { text: '👛 E-Wallet', data: 'pay_ewallet' }]], pending_row: pr(m.chat_id, 'beli_metode', d) } }];
}
if (stage === 'beli_metode' && metodeToken) {
  d.metode = metodeToken.replace('-', '');
  return [{ json: { chat_id: m.chat_id, text: 'Masuk kategori apa?', kb: [[{ text: '🧺 Bahan Baku', data: 'cat_bb' }, { text: '⚙️ Operasional', data: 'cat_ops' }], [{ text: '🏠 Sewa', data: 'cat_sewa' }, { text: '👷 Gaji', data: 'cat_gaji' }], [{ text: '📦 Lainnya', data: 'cat_lain' }]], pending_row: pr(m.chat_id, 'beli_cat', d) } }];
}
